from types import SimpleNamespace

from fastapi.testclient import TestClient

from gpt2giga.api_server import create_app
from gpt2giga.models.config import ProxyConfig, ProxySettings


class MockResponse:
    def __init__(self, data):
        self.data = data

    def model_dump(self, *args, **kwargs):
        return self.data


class FakeModel:
    def model_dump(self, by_alias=True):
        return {
            "id": "GigaChat",
            "object": "model",
            "owned_by": "gigachat",
        }


class FakeAChatResource:
    async def __call__(self, chat):
        return MockResponse(
            {
                "choices": [
                    {
                        "message": {"role": "assistant", "content": "Hello!"},
                        "finish_reason": "stop",
                    }
                ],
                "usage": {
                    "prompt_tokens": 10,
                    "completion_tokens": 5,
                    "total_tokens": 15,
                },
            }
        )

    async def create(self, chat):
        return MockResponse(
            {
                "model": chat.get("model", "GigaChat"),
                "messages": [
                    {
                        "role": "assistant",
                        "content": [{"text": "Hello!"}],
                    }
                ],
                "finish_reason": "stop",
                "usage": {
                    "input_tokens": 10,
                    "output_tokens": 5,
                    "total_tokens": 15,
                },
            }
        )


class FakeGigaChat:
    def __init__(self, **kwargs):
        self.achat = FakeAChatResource()

    async def aget_models(self):
        return SimpleNamespace(data=[FakeModel()], object_="list")

    async def aget_model(self, model: str):
        return SimpleNamespace(id_=model)

    async def aclose(self):
        return None


class FakeRequestTransformer:
    async def prepare_chat(self, data, giga_client=None):
        return {
            "model": data.get("model", "giga"),
            "messages": data.get("messages", []),
            "tools": data.get("tools"),
            "function_call": data.get("function_call"),
            "functions": data.get("functions"),
            "reasoning_effort": data.get("reasoning_effort"),
        }

    async def prepare_chat_completion(self, data, giga_client=None):
        return {
            "model": data.get("model", "giga"),
            "messages": data.get("messages", []),
            "tools": data.get("tools"),
            "function_call": data.get("function_call"),
            "functions": data.get("functions"),
            "reasoning_effort": data.get("reasoning_effort"),
        }


def make_app(monkeypatch):
    config = ProxyConfig(
        proxy=ProxySettings(
            mode="DEV",
            log_filename="/tmp/gpt2giga-ci-smoke.log",
            gigachat_api_mode="v1",
        )
    )
    monkeypatch.setattr(
        "gpt2giga.app.lifecycle.create_gigachat_client",
        lambda settings: FakeGigaChat(),
    )
    return create_app(config=config)


def install_fake_transformer(app):
    app.state.request_transformer = FakeRequestTransformer()


def test_ci_smoke_health(monkeypatch):
    app = make_app(monkeypatch)

    with TestClient(app) as client:
        response = client.get("/health")

    assert response.status_code == 200


